content.content:
.banner-section {
  color: #fff;
  background-color: #082753;
  width: 100%;
  padding: 10px 5%;
  position: relative;
}
.nav-23-logo {
  width: 130px;
  height: 100%;
  padding-left: 0;
  padding-right: 0;
}
.nav-23-container {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  justify-content: space-between;
  width: 100%;
  max-width: none;
  margin-left: auto;
  margin-right: auto;
  display: flex;
}
.nav-23-dropdown-link {
  grid-column-gap: 12px;
  grid-row-gap: 12px;
  color: #082753;
  white-space: nowrap;
  border-radius: 8px;
  padding: 8px 24px 8px 8px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 16px;
  font-weight: 500;
  text-decoration: none;
  transition: background-color .3s;
  display: flex;
}
.nav-23-dropdown-link:hover {
  background-color: #21cfff12;
}
.nav-23-menu-line {
  transform-origin: center;
  background-color: currentColor;
  border-radius: 4px;
  width: 20px;
  height: 2px;
}
.nav-23-menu-line.line-middle {
  top: 50%;
}
.nav-23-menu-line.line-bottom {
  bottom: 0;
}
.nav-23-menu-burger {
  grid-column-gap: 4px;
  grid-row-gap: 4px;
  flex-flow: column;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
}
.nav-23-left {
  grid-column-gap: 40px;
  grid-row-gap: 40px;
  flex: 0 auto;
  justify-content: flex-start;
  align-items: center;
  display: flex;
}
.nav-23-dropdown-arrow {
  color: #082753;
  justify-content: center;
  align-items: center;
  width: 24px;
  height: 24px;
  padding: 6px 2px 2px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-weight: 500;
  display: flex;
}
.nav-23-links {
  grid-column-gap: 2px;
  grid-row-gap: 2px;
  justify-content: flex-start;
  align-items: center;
  display: flex;
}
.nav-23-dropdown-links {
  grid-column-gap: 2px;
  grid-row-gap: 2px;
  flex-flow: column;
  display: flex;
}
.navbar {
  z-index: 999999;
  text-align: center;
  background-color: #fff;
  width: 100%;
  padding: 6px 1%;
  position: relative;
}
.nav-23-menu-button {
  color: #fff;
  background-color: #000;
  border-radius: 10px;
  flex: none;
  width: 48px;
  height: 48px;
  padding: 0;
}
.nav-23-menu-button.w--open {
  background-color: #000;
}
.nav-23-right {
  grid-column-gap: 12px;
  grid-row-gap: 12px;
  flex: 0 auto;
  justify-content: flex-end;
  align-items: center;
  display: flex;
}
.nav-23-link {
  color: #000;
  white-space: nowrap;
  background-color: #0000;
  border-radius: 8px;
  padding: 8px 5px;
  text-decoration: none;
  transition: background-color .3s, color .3s;
}
.nav-23-link:hover {
  color: #000;
  background-color: #0000;
}
.nav-23-link.w--current {
  color: #000;
}
.nav-23-dropdown-card {
  background-color: #fff;
  border: 1px solid #dde3e8;
  border-radius: 12px;
  min-width: 190px;
  padding: 8px;
  overflow: hidden;
}
.nav-23-menu {
  align-items: center;
  display: flex;
  position: static;
}
.nav-23-dropdown-list {
  background-color: #0000;
}
.nav-23-dropdown-list.w--open {
  background-color: #0000;
  padding-top: 20px;
}
.nav-23-dropdown {
  margin-left: 0;
  margin-right: 0;
}
.nav-23-dropdown-toggle {
  grid-column-gap: 4px;
  grid-row-gap: 4px;
  color: #000;
  white-space: nowrap;
  background-color: #0000;
  border-radius: 8px;
  justify-content: flex-start;
  align-items: center;
  padding: 8px 8px 8px 10px;
  font-size: 16px;
  line-height: 1.5;
  text-decoration: none;
  transition: background-color .3s, color .3s;
  display: flex;
}
.nav-23-dropdown-toggle:hover {
  color: #000;
  background-color: #0000;
}
.nav-23-dropdown-toggle.w--current {
  color: #000;
}
.nav-23-dropdown-toggle.w--open {
  background-color: #f5f7f8;
}
.nav-23-dropdown-toggle.last-child.w--open {
  transition: background-color .3s, color .3s;
}
.header-sec {
  text-align: center;
  background-color: #fff;
  flex-flow: column;
  justify-content: flex-start;
  align-items: center;
  display: flex;
}
.nav-dropdown-card {
  grid-column-gap: 24px;
  grid-row-gap: 24px;
  background-color: #fff;
  border: 1px solid #f1f1f1;
  border-radius: 20px;
  flex-flow: column;
  grid-template-rows: auto;
  grid-template-columns: 1fr 3fr;
  grid-auto-columns: 1fr;
  width: 92vw;
  max-width: none;
  padding: 24px;
  display: flex;
}
.nav-dropdown-list {
  background-color: #0000;
  padding-top: 12px;
  overflow: hidden;
}
.nav-dropdown-list.w--open {
  left: -40px;
}
.nav-dropdown-list.nav-dropdown-03.w--open {
  margin-top: 16px;
  top: auto;
  left: -130px;
}
.nav-dropdown {
  background-color: #0000;
  border-radius: 0;
  justify-content: flex-start;
  align-items: center;
  padding-top: 8px;
  padding-bottom: 8px;
  display: block;
}
.nav-dropdown-toggle {
  grid-column-gap: 4px;
  grid-row-gap: 4px;
  letter-spacing: -.006em;
  background-color: #0000;
  border-radius: 0;
  justify-content: flex-start;
  align-items: center;
  width: 100%;
  padding: 8px 8px 8px 12px;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  display: flex;
}
.nav-dropdown-toggle:hover {
  background-color: #0000;
}
.nav-dropdown-toggle.w--open {
  background-color: #fff;
}
.nav-dropdown-link {
  color: #2b2b2b;
  letter-spacing: -.006em;
  padding-top: 4px;
  padding-bottom: 4px;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 20px;
  text-decoration: none;
  transition: color .3s;
}
.nav-dropdown-link:hover {
  color: #1a1925;
}
.nav-dropdown-list-2 {
  background-color: #0000;
}
.nav-dropdown-list-2.w--open {
  background-color: #0000;
  padding-top: 10px;
}
.nav-dropdown-slot {
  min-width: 410px;
  min-height: 150px;
  padding-top: 3px;
}
.nav-dropdown-slot.medium {
  min-width: 570px;
}
.nav-dropdown-grid {
  grid-column-gap: 12px;
  grid-row-gap: 12px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr;
  display: grid;
}
.nav-dropdown-card-2 {
  background-color: #fff;
  border-radius: 12px;
  padding: 12px;
  overflow: hidden;
  box-shadow: 0 109.603px 30.372px #0000, 0 69.987px 27.731px #00000003, 0 39.615px 23.769px #0000000a, 0 17.167px 17.167px #00000012, 0 3.962px 9.244px #00000014;
}
.nav-dropdown-link-2 {
  grid-column-gap: 12px;
  grid-row-gap: 12px;
  color: #18181b;
  border-radius: 8px;
  padding: 12px 24px 12px 8px;
  text-decoration: none;
  transition: background-color .3s;
  display: flex;
}
.nav-dropdown-link-2:hover {
  background-color: #21cfff12;
}
.nav-dropdown-link-2.border-btm {
  border-bottom: 1px solid #f5f5f5;
  padding-top: 12px;
  padding-bottom: 12px;
}
.nav-dropdown-link-2.border-btm:hover {
  background-color: #21cfff12;
}
.nav-dropdown-link-2.border-btm.disabled, .nav-dropdown-link-2.disabled {
  pointer-events: none;
  cursor: pointer;
}
.nav-dropdown-arrow {
  justify-content: center;
  align-items: center;
  width: 20px;
  height: 20px;
  padding: 2px;
  display: flex;
}
.nav-dropdown-icon {
  flex: none;
  justify-content: center;
  align-items: center;
