#### **Sticky Navbar JavaScript**

```javascript
<script>
document.addEventListener('DOMContentLoaded', () => {
  const header = document.querySelector('.navbar.w-nav');
  if (!header) return;

  const getOffset = () => (window.matchMedia('(max-width: 767px)').matches ? 350 : 300);
  let offset = getOffset();
  let isSticky = false;
  let headerHeight = header.offsetHeight;

  window.addEventListener('resize', () => {
    offset = getOffset();
    headerHeight = header.offsetHeight;
  });

  window.addEventListener('scroll', () => {
    window.requestAnimationFrame(() => {
      if (window.scrollY > offset && !isSticky) {
        header.classList.add('sticky');
        document.body.style.paddingTop = `${headerHeight}px`;
        isSticky = true;
      } else if (window.scrollY <= offset && isSticky) {
        header.classList.remove('sticky');
        document.body.style.paddingTop = '';
        isSticky = false;
      }
    });
  });
});
</script>
```

#### **Mobile Menu Scroll Lock JavaScript**

```javascript
<script>
document.addEventListener('DOMContentLoaded', () => {
  const menuButton = document.querySelector('.w-nav-button');
  const body = document.body;
  if (!menuButton) return;

  const toggleScroll = () => {
    if (menuButton.classList.contains('w--open')) {
      body.style.overflow = 'hidden'; // disable scroll
    } else {
      body.style.overflow = ''; // enable scroll
    }
  };

  // Listen for open/close changes
  const observer = new MutationObserver(() => {
    toggleScroll();
  });

  observer.observe(menuButton, { attributes: true, attributeFilter: ['class'] });
});
</script>
```

